package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.io.File;
import java.util.Set;

import org.eclipse.rdf4j.common.iteration.CloseableIteration;
import org.eclipse.rdf4j.common.order.StatementOrder;
import org.eclipse.rdf4j.common.transaction.IsolationLevels;
import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.Statement;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.sail.NotifyingSailConnection;
import org.eclipse.rdf4j.sail.SailException;
import org.eclipse.rdf4j.sail.base.SailDataset;
import org.eclipse.rdf4j.sail.lmdb.TxnManager.Txn;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * A store map resize renews even pinned read transactions onto a newer LMDB snapshot. Every read path of a pinned
 * SNAPSHOT transaction must then fail loudly instead of silently serving data from the wrong snapshot.
 */
public class LmdbSnapshotInvalidationTest {

	private static final long PRED = 42;

	@TempDir
	File dataDir;

	private TripleStore tripleStore;

	@BeforeEach
	public void setUp() throws Exception {
		tripleStore = new TripleStore(new File(dataDir, "triplestore"), new LmdbStoreConfig("spoc,posc"), null);
		tripleStore.startTransaction();
		for (long subj = 1; subj <= 100; subj++) {
			tripleStore.storeTriple(subj, PRED, 1000 + subj, 0, true);
		}
		tripleStore.commit();
	}

	@AfterEach
	public void tearDown() throws Exception {
		if (tripleStore != null) {
			tripleStore.close();
			tripleStore = null;
		}
	}

	private void simulateMapResize() throws Exception {
		// exactly what TripleStore does around mdb_env_set_mapsize: park all read txns, then renew them
		tripleStore.getTxnManager().deactivate();
		tripleStore.getTxnManager().activate();
	}

	@Test
	public void pinnedIteratorFailsInsteadOfRenewingAfterMapResize() throws Exception {
		try (Txn pinned = tripleStore.getTxnManager().createReadTxnPinned(tripleStore::getDataRevision)) {
			try (RecordIterator it = tripleStore.getTriples(pinned, -1, PRED, -1, -1, true)) {
				assertThat(it.next()).isNotNull();
				simulateMapResize();
				assertThatThrownBy(it::next).isInstanceOf(SailException.class)
						.hasMessageContaining("SNAPSHOT");
			}
		}
	}

	@Test
	public void unpinnedIteratorStillRenewsSilently() throws Exception {
		try (Txn txn = tripleStore.getTxnManager().createReadTxn()) {
			try (RecordIterator it = tripleStore.getTriples(txn, -1, PRED, -1, -1, true)) {
				assertThat(it.next()).isNotNull();
				simulateMapResize();
				int remaining = 0;
				while (it.next() != null) {
					remaining++;
				}
				assertThat(remaining).isEqualTo(99);
			}
		}
	}

	@Test
	public void datasetReadPathsFailOnInvalidatedSnapshot() throws Exception {
		LmdbStore store = new LmdbStore(new File(dataDir, "store"), new LmdbStoreConfig("spoc,posc"));
		store.init();
		try {
			ValueFactory vf = SimpleValueFactory.getInstance();
			IRI pred = vf.createIRI("http://example.com/p");
			IRI ctx = vf.createIRI("http://example.com/g");
			try (NotifyingSailConnection connection = store.getConnection()) {
				connection.begin();
				for (int i = 0; i < 10; i++) {
					connection.addStatement(vf.createIRI("http://example.com/s" + i), pred,
							vf.createIRI("http://example.com/o" + i), ctx);
				}
				connection.commit();
			}

			LmdbSailStore backing = store.getBackingStore();
			try (SailDataset dataset = backing.getExplicitSailSource().dataset(IsolationLevels.SNAPSHOT)) {
				Set<StatementOrder> orders = dataset.getSupportedOrders(null, null, null);
				assertThat(orders).isNotEmpty();
				StatementOrder order = orders.iterator().next();

				backing.getTripleStore().getTxnManager().deactivate();
				backing.getTripleStore().getTxnManager().activate();

				// plain statement reads were already guarded; the same failure is required on every read path
				assertThatThrownBy(() -> {
					try (CloseableIteration<? extends Statement> it = dataset.getStatements(null, null, null)) {
						it.hasNext();
					}
				}).isInstanceOf(SailException.class).hasMessageContaining("SNAPSHOT");

				assertThatThrownBy(() -> {
					try (CloseableIteration<?> it = dataset.getContextIDs()) {
						it.hasNext();
					}
				}).isInstanceOf(SailException.class).hasMessageContaining("SNAPSHOT");

				assertThatThrownBy(() -> {
					try (CloseableIteration<? extends Statement> it = dataset.getStatements(order, null, null, null)) {
						it.hasNext();
					}
				}).isInstanceOf(SailException.class).hasMessageContaining("SNAPSHOT");

				assertThatThrownBy(() -> {
					try (CloseableIteration<?> it = dataset.getTriples(null, null, null)) {
						it.hasNext();
					}
				}).isInstanceOf(SailException.class).hasMessageContaining("SNAPSHOT");
			}
		} finally {
			store.shutDown();
		}
	}
}
